function validate([houses, cost, m, n, target]) {
  const whole = v => Number.isInteger(v);
  if (!whole(m) || m < 1 || m > 100) return 'm is between 1 and 100.';
  if (!whole(n) || n < 1 || n > 20) return 'n is between 1 and 20.';
  if (!Array.isArray(houses) || houses.length !== m) return 'houses needs exactly m entries.';
  if (!Array.isArray(cost) || cost.length !== m) return 'cost needs exactly m rows.';
  if (cost.some(row => !Array.isArray(row) || row.length !== n)) return 'Each cost row needs exactly n prices.';
  if (houses.some(h => !whole(h) || h < 0 || h > n)) return 'Each house color is between 0 and n.';
  if (cost.some(row => row.some(c => !whole(c) || c < 1 || c > 10000))) return 'Each price is between 1 and 10^4.';
  if (!whole(target) || target < 1 || target > m) return 'target is between 1 and m.';
  return null;
}

