function minCost(houses, cost, m, n, target) {
  let dp = Array.from({ length: n + 1 }, () => new Array(target + 1).fill(Infinity));
  for (let color = 1; color <= n; color++) {
    if (houses[0] === 0) {
      dp[color][1] = cost[0][color - 1];
    } else if (houses[0] === color) {
      dp[color][1] = 0;
    }
  }

  for (let i = 1; i < m; i++) {
    const next = Array.from({ length: n + 1 }, () => new Array(target + 1).fill(Infinity));
    for (let color = 1; color <= n; color++) {
      if (houses[i] !== 0 && houses[i] !== color) continue;
      const paint = houses[i] === 0 ? cost[i][color - 1] : 0;
      for (let groups = 1; groups <= target; groups++) {
        for (let prev = 1; prev <= n; prev++) {
          const before = prev === color ? dp[prev][groups] : dp[prev][groups - 1];
          next[color][groups] = Math.min(next[color][groups], before + paint);
        }
      }
    }
    dp = next;
  }

  let best = Infinity;
  for (let color = 1; color <= n; color++) {
    best = Math.min(best, dp[color][target]);
  }
  return best === Infinity ? -1 : best;
}

