function minCost(houses, cost, m, n, target) {
  let best = -1;
  const colors = houses.slice();
  const search = (i, spent) => {
    if (i === m) {
      let count = 0;
      for (let k = 0; k < m; k++) if (k === 0 || colors[k] !== colors[k - 1]) count++;
      if (count === target && (best === -1 || spent < best)) best = spent;
      return;
    }
    if (houses[i] !== 0) { search(i + 1, spent); return; }
    for (let c = 1; c <= n; c++) {
      colors[i] = c;
      search(i + 1, spent + cost[i][c - 1]);
    }
    colors[i] = 0;
  };
  search(0, 0);
  return best;
}

