function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(80, 100) : int(1, 6);
  const n = large ? int(2, 20) : int(1, 3);
  const paintedShare = rand() * (large ? 0.4 : 0.6);
  const houses = Array.from({ length: m }, () => rand() < paintedShare ? int(1, n) : 0);
  const top = large ? 10000 : int(1, 12);
  const cost = Array.from({ length: m }, () => Array.from({ length: n }, () => int(1, top)));
  const target = large ? int(1, Math.max(1, Math.floor(m * 0.6))) : int(1, m);
  return [houses, cost, m, n, target];
}
